import {seed} from './seed.js';
import {today,quarter,progress,health,scopeProjects,monthlySeries,validateData} from './model.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',folder:'M3 7V4h6l3 3h9v13H3z',task:'m8 6 2 2 4-4 M16 7h5 M3 13h18 M3 19h18 M3 6h1',road:'M4 4v16 M20 4v16 M4 8h11 M9 16h11',chart:'M4 4v16h17 M8 15l4-5 4 2 5-7',risk:'M12 3 2 21h20z M12 9v5 M12 17v1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 m5 12 6 6',close:'m6 6 12 12 M6 18 18 6',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',check:'m5 12 4 4L19 6',leaf:'M20 3C6 1 1 11 7 17c6 6 15-1 13-14Z M5 21 16 9',menu:'M4 6h16 M4 12h16 M4 18h16',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',edit:'m16 3 5 5-12 12-6 1 1-6z M14 5l5 5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.folder}"/></svg>`;
const key='prosjektledelse.v1';let data,loadError=false;try{const saved=localStorage.getItem(key);data=saved?validateData(JSON.parse(saved)):seed()}catch{data=seed();loadError=true}
let state={page:location.hash.slice(1)||'overview',year:new Date().getFullYear(),q:0,search:'',taskStatus:'All statuses',project:'all',taskView:'list'};
const names={overview:'Overview',projects:'Projects',tasks:'Tasks',roadmap:'Quarterly roadmap',insights:'Insights',risks:'Risks',settings:'Workspace settings'};
if(!names[state.page])state.page='overview';
const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}),money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'NOK',maximumFractionDigits:0}).format(n),shortMoney=n=>n>=1000?`${Math.round(n/1000)}k`:String(n),initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join(''),id=()=>crypto.randomUUID();
const findP=id=>data.projects.find(p=>p.id===id),pname=id=>findP(id)?.name||'Unassigned',scoped=()=>scopeProjects(data,state.year,state.q,state.search),tasksFor=projects=>data.tasks.filter(t=>projects.some(p=>p.id===t.projectId));
function save(message){try{localStorage.setItem(key,JSON.stringify(data));$('#save-state').textContent='Saved on this device';if(message)toast(message)}catch{$('#save-state').textContent='Changes not saved — export a backup';toast('Device storage is unavailable or full. Export a backup to keep your work.')}}
function log(text){data.activity.unshift({id:id(),text,at:new Date().toISOString()});data.activity=data.activity.slice(0,100)}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function badge(status){return `<span class="badge ${status==='At risk'||status==='Blocked'?'risk':status==='Off track'?'off':status==='Complete'||status==='Done'?'complete':''}">${esc(status)}</span>`}
function avatar(name,color=''){return `<span class="avatar ${color}" aria-hidden="true">${esc(initials(name))}</span>`}
function bar(value,color=''){return `<div class="bar ${color}" role="meter" aria-label="Progress" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="100"><i style="width:${value}%"></i></div>`}
function empty(text,button=''){return `<div class="empty">${icon('leaf')}<div>${text}</div>${button?`<p>${button}</p>`:''}</div>`}
function render(){
$('#sidebar').innerHTML=`<a href="#overview" class="brand"><img class="brandmark" src="icon.svg" alt="">Prosjektledelse</a><div class="workspace-switch"><span>${icon('leaf')}</span><div>${esc(data.workspace)}<small>Your planning space</small></div></div><p class="nav-label">Workspace</p><nav>${Object.entries(names).filter(([k])=>k!=='settings').map(([k,v])=>`<button data-nav="${k}" class="${state.page===k?'active':''}" ${state.page===k?'aria-current="page"':''}>${icon(({overview:'grid',projects:'folder',tasks:'task',roadmap:'road',insights:'chart',risks:'risk'})[k])}${v}${k==='projects'?`<span class="count">${data.projects.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="quiet-card">${icon('leaf')}<p>Good things take shape<br>one thoughtful step at a time.</p></div><nav><button data-nav="settings" class="${state.page==='settings'?'active':''}">${icon('settings')}Settings & backups</button></nav><div class="user">${avatar('Personal workspace')}<div>Personal workspace<small>Saved on this device</small></div></div></div>`;
$('#topbar').innerHTML=`<div class="breadcrumb"><button id="menu-toggle" class="ghost" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><span>Workspace</span><span>/</span><b>${names[state.page]}</b></div><div class="top-right">${data.demo?'<span class="demo-pill">Example workspace</span>':''}<span class="date">${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'long',year:'numeric'})}</span>${avatar('Personal workspace')}</div>`;
$('#main').innerHTML=({overview,projects,tasks,roadmap,insights,risks,settings})[state.page]();
}
function heading(title,sub,actions=''){return `<div class="heading"><div><p class="eyebrow">${state.page==='overview'?'A LITTLE CLARITY, EVERY DAY':names[state.page]}</p><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function yearSelect(){const years=[...new Set([state.year-1,state.year,state.year+1,...data.projects.flatMap(p=>[+p.start.slice(0,4),+p.due.slice(0,4)])])].sort();return `<select id="year" aria-label="Planning year">${years.map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}</select>`}
function periodbar(){return `<div class="periodbar"><div class="segmented" role="group" aria-label="Quarter filter">${[0,1,2,3,4].map(q=>`<button data-quarter="${q}" class="${state.q===q?'active':''}" aria-pressed="${state.q===q}">${q?'Q'+q:'Full year'}</button>`).join('')}</div><span class="note">${state.q?`Q${state.q} · `:''}${state.year} · ${scoped().length} projects in view</span></div>`}
function metrics(ps){const ts=tasksFor(ps),done=ts.filter(t=>t.status==='Done').length,pct=ts.length?Math.round(done/ts.length*100):0,active=ps.filter(p=>progress(p,data.tasks)<100).length,atRisk=ps.filter(p=>['At risk','Off track'].includes(health(p,data.tasks))).length,spent=ps.reduce((a,p)=>a+p.spent,0),budget=ps.reduce((a,p)=>a+p.budget,0);return `<div class="stats">${[["Active projects",active,'folder',`${ps.length-active} completed ${ps.length-active===1?'project':'projects'}`],["Overall progress",`${pct}<small>%</small>`,'chart',`${done} of ${ts.length} tasks completed`],["Need attention",atRisk,'risk',`${ts.filter(t=>t.status==='Blocked').length} blocked · ${ts.filter(t=>t.status!=='Done'&&t.due<today()).length} overdue tasks`],["Budget used",`${budget?Math.round(spent/budget*100):0}<small>%</small>`,'grid',`${shortMoney(spent)} of ${shortMoney(budget)} NOK`]].map(([l,v,i,f])=>`<div class="stat"><div class="stat-label">${l}${icon(i)}</div><div class="stat-value">${v}</div><div class="stat-foot">${f}</div></div>`).join('')}</div>`}
function chart(ps){const s=monthlySeries(data,state.year,ps.map(p=>p.id));const currentYear=new Date().getFullYear(),last=state.year<currentYear?11:state.year>currentYear?-1:new Date().getMonth();const line=(field,list)=>list.map((v,i)=>`${i?'L':'M'}${40+v.month*45},${170-v[field]*1.4}`).join(' ');const actual=s.filter((v,i)=>i<=last);return `<svg class="chart" viewBox="0 0 560 205" role="img" aria-label="Cumulative completed tasks versus scheduled completion by month. Actual data ends at the current month."><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#d8e1c9" stop-opacity=".6"/><stop offset="1" stop-color="#d8e1c9" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(n=>`<line x1="40" x2="535" y1="${170-n*1.4}" y2="${170-n*1.4}" stroke="#e7eadf" stroke-dasharray="3 5"/><text x="4" y="${174-n*1.4}">${n}%</text>`).join('')}${actual.length?`<path d="${line('actual',actual)} L${40+last*45},170 L40,170Z" fill="url(#chart-fill)"/>`:''}<path d="${line('planned',s)}" fill="none" stroke="#b5bda8" stroke-width="2" stroke-dasharray="5 5"/>${actual.length?`<path d="${line('actual',actual)}" fill="none" stroke="#6b805b" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${40+last*45}" cy="${170-actual.at(-1).actual*1.4}" r="4" fill="#6b805b" stroke="#fffefa" stroke-width="2"/>`:''}${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].map((m,i)=>`<text x="${40+i*45}" y="199" text-anchor="middle">${m}</text>`).join('')}</svg>`}
function trendPanel(ps){const ts=tasksFor(ps),monthAgo=new Date();monthAgo.setDate(monthAgo.getDate()-30);const recent=ts.filter(t=>t.status==='Done'&&t.completedAt>=monthAgo.toLocaleDateString('en-CA')).length;return `<section class="panel"><div class="panel-head"><div><h2>Progress, over time</h2><p>Cumulative task completion · ${state.year}</p></div><div class="chart-key"><span>Actual</span><span class="plan">Planned</span></div></div><div class="panel-body">${chart(ps)}<div class="chart-summary">${icon('leaf')}<span>${recent} ${recent===1?'task':'tasks'} completed in the last 30 days. Every step counts.</span></div></div></section>`}
function quarters(){return `<div class="quarter-grid">${[1,2,3,4].map(q=>{const ps=scopeProjects(data,state.year,q),ts=tasksFor(ps).filter(t=>+t.due.slice(0,4)===state.year&&quarter(t.due)===q),done=ts.filter(t=>t.status==='Done').length,p=ts.length?Math.round(done/ts.length*100):0;return `<button class="quarter-card ${state.q===q?'selected':''}" data-quarter="${q}" aria-pressed="${state.q===q}"><b>Q${q}</b><span>${['January – March','April – June','July – September','October – December'][q-1]}</span><strong>${p}% <span style="display:inline;font-size:.6875rem">completed</span></strong>${bar(p)}<span>${done} / ${ts.length} tasks · ${ps.length} projects</span></button>`}).join('')}</div>`}
function projectTable(ps){return ps.length?`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Status</th><th>Progress</th><th>Lead</th><th>Due date</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="project-name"><span class="project-icon ${p.color}">${icon('folder')}</span><button data-detail="${p.id}">${esc(p.name)}</button></div></td><td>${badge(health(p,data.tasks))}</td><td><div class="progress-cell">${bar(progress(p,data.tasks),p.color)}${progress(p,data.tasks)}%</div></td><td><span class="owner">${avatar(p.owner,p.color)}${esc(p.owner.split(' ')[0])}</span></td><td>${fmt(p.due)}</td><td><button data-new-project-task="${p.id}" aria-label="Add task to ${esc(p.name)}">${icon('plus')}Add task</button> <button class="ghost" data-edit="project:${p.id}" aria-label="Edit ${esc(p.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('A little room for your next idea.',`<button data-action="new-project">Create a project</button>`)}
function milestones(ps,all=false){const ms=data.milestones.filter(m=>ps.some(p=>p.id===m.projectId)&&(all||!m.done)).sort((a,b)=>a.due.localeCompare(b.due));return ms.length?ms.slice(0,all?100:4).map(m=>`<div class="focus-item"><div class="date-box">${new Date(m.due+'T12:00:00').toLocaleDateString('en-GB',{month:'short'}).toUpperCase()}<strong>${+m.due.slice(8)}</strong></div><div><b>${esc(m.name)} ${m.done?'✓':''}</b><small>${esc(pname(m.projectId))}</small>${!m.done&&m.due<today()?'<small class="overdue">Overdue</small>':''}</div><button class="text-button" data-edit="milestone:${m.id}" aria-label="Edit ${esc(m.name)}">${icon('edit')}</button></div>`).join(''):empty('No upcoming milestones. Make space for the next one.')}
function overview(){const ps=scoped();return heading('A clear view of what’s next.','Your projects, plans, and progress — with room to breathe.',`${yearSelect()}<button data-action="export-csv">${icon('download')}Export</button><button class="primary" data-action="new-project">${icon('plus')}New project</button>`)+periodbar()+metrics(ps)+`<div class="overview-grid">${trendPanel(ps)}<section class="panel"><div class="panel-head"><div><h2>On the horizon</h2><p>Your next milestones</p></div><button class="text-button" data-action="new-milestone" aria-label="Add milestone">${icon('plus')}</button></div><div class="panel-body">${milestones(ps)}</div></section></div><div class="section-title"><h2>A year, thoughtfully planned</h2><button class="text-button" data-nav="roadmap">Open roadmap</button></div>${quarters()}<section class="panel"><div class="panel-head" style="padding-bottom:20px"><div><h2>Project portfolio</h2><p>The moving parts, in one place.</p></div><button class="text-button" data-nav="projects">All projects</button></div>${projectTable(ps)}</section>`}
function projects(){const ps=scoped();return heading('Ideas into meaningful progress.','A considered home for every project.',`${yearSelect()}<button class="primary" data-action="new-project">${icon('plus')}New project</button>`)+periodbar()+`<div class="toolbar"><input id="project-search" placeholder="Search projects or leads…" aria-label="Search projects" value="${esc(state.search)}"><span class="note">${ps.length} projects</span></div>`+(ps.length?`<div class="project-cards">${ps.map(p=>`<article class="panel project-card"><div class="card-top"><span class="project-icon ${p.color}">${icon('folder')}</span>${badge(health(p,data.tasks))}</div><h2><button class="text-button" style="font-size:1rem;color:inherit" data-detail="${p.id}">${esc(p.name)}</button></h2><p>${esc(p.description)}</p><div><div class="meta-row"><span>Task completion</span><span>${progress(p,data.tasks)}%</span></div>${bar(progress(p,data.tasks),p.color)}</div><div class="meta-row"><span class="owner">${avatar(p.owner,p.color)}${esc(p.owner)}</span><span>${fmt(p.due)}</span></div><div class="meta-row"><span>${money(p.spent)} / ${shortMoney(p.budget)}</span><button class="text-button" data-edit="project:${p.id}">Edit project</button></div><div class="project-task-actions"><button class="primary" data-new-project-task="${p.id}" aria-label="Add task to ${esc(p.name)}">${icon('plus')}Add task</button><button data-detail="${p.id}">View tasks (${data.tasks.filter(t=>t.projectId===p.id).length})</button></div></article>`).join('')}</div>`:empty('No projects match this view.'))}
function projectOptions(selected='all',all=true){return `${all?'<option value="all">All projects</option>':''}${data.projects.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}`}
function visibleTasks(){return tasksFor(scoped()).filter(t=>(state.project==='all'||t.projectId===state.project)&&(state.taskStatus==='All statuses'||t.status===state.taskStatus))}
function tasks(){const ts=visibleTasks();return heading('Make space for focused work.','Small steps, shared ownership, steady momentum.',`${yearSelect()}<button class="primary" data-action="new-task">${icon('plus')}New task</button>`)+periodbar()+`<div class="toolbar"><select id="project-filter" aria-label="Filter tasks by project">${projectOptions(state.project)}</select><select id="status-filter" aria-label="Filter tasks by status">${['All statuses','To do','In progress','Blocked','Done'].map(s=>`<option ${s===state.taskStatus?'selected':''}>${s}</option>`).join('')}</select><div class="segmented">${['list','board'].map(v=>`<button data-view="${v}" class="${state.taskView===v?'active':''}" aria-pressed="${state.taskView===v}">${v==='list'?'List':'Board'}</button>`).join('')}</div><span class="note">${ts.length} tasks</span></div>`+(state.taskView==='board'?`<div class="board">${['To do','In progress','Blocked','Done'].map(s=>`<section class="board-column"><h2>${s}<span>${ts.filter(t=>t.status===s).length}</span></h2>${ts.filter(t=>t.status===s).map(t=>`<div class="task-card"><button data-edit="task:${t.id}">${esc(t.name)}</button><small>${esc(pname(t.projectId))}</small><div class="task-meta"><span class="priority ${t.priority==='High'?'high':''}">${t.priority} priority</span><span class="board-responsible">${esc(t.owner)}</span></div><small class="${t.status!=='Done'&&t.due<today()?'overdue':''}">${fmt(t.due)}</small></div>`).join('')}</section>`).join('')}</div>`:ts.length?`<section class="panel table-wrap"><table><thead><tr><th>Task</th><th>Project</th><th>Status</th><th>Priority</th><th>Responsible</th><th>Deadline</th><th></th></tr></thead><tbody>${ts.map(t=>`<tr><td><div class="owner"><input type="checkbox" data-complete="${t.id}" ${t.status==='Done'?'checked':''} aria-label="Mark ${esc(t.name)} complete"><button class="text-button" style="color:inherit;text-align:left" data-edit="task:${t.id}">${esc(t.name)}</button></div></td><td>${esc(pname(t.projectId))}</td><td>${badge(t.status)}</td><td><span class="priority ${t.priority==='High'?'high':''}">${t.priority}</span></td><td>${esc(t.owner)}</td><td class="${t.status!=='Done'&&t.due<today()?'overdue':''}">${fmt(t.due)}</td><td><button class="text-button" data-edit="task:${t.id}" aria-label="Edit task">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></section>`:empty('No tasks in this view.'))}
function roadmap(){const ps=scoped();return heading('See the shape of your year.','Quarterly direction, connected to the work that gets you there.',`${yearSelect()}<button class="primary" data-action="new-milestone">${icon('plus')}New milestone</button>`)+periodbar()+quarters()+`<section class="panel table-wrap"><div class="timeline"><div class="timeline-row timeline-header"><div>Project timeline</div>${[1,2,3,4].map(q=>`<div>Q${q} · ${['Jan–Mar','Apr–Jun','Jul–Sep','Oct–Dec'][q-1]}</div>`).join('')}</div>${ps.map(p=>`<div class="timeline-row"><div><button class="text-button" style="color:inherit" data-detail="${p.id}">${esc(p.name)}</button></div>${[1,2,3,4].map(q=>`<div>${scopeProjects({projects:[p]},state.year,q).length?`<button class="timeline-bar ${p.color}" data-detail="${p.id}" aria-label="${esc(p.name)} in Q${q}">${q===Math.max(1,+p.start.slice(0,4)<state.year?1:quarter(p.start))?esc(p.owner.split(' ')[0]):'· · ·'} <span style="float:right">${progress(p,data.tasks)}%</span></button>`:''}</div>`).join('')}</div>`).join('')}</div></section><div class="section-title"><h2>Milestones & checkpoints</h2><span class="note">Includes completed milestones</span></div><div class="panel panel-body">${milestones(ps,true)}</div>`}
function insights(){const ps=scoped(),ts=tasksFor(ps),blocked=ts.filter(t=>t.status==='Blocked').length;return heading('Understand the momentum.','Useful signals for thoughtful decisions.',`${yearSelect()}<button data-action="export-csv">${icon('download')}Export report</button>`)+periodbar()+metrics(ps)+`<div class="insight-grid">${trendPanel(ps)}<section class="panel"><div class="panel-head"><div><h2>Budget, in balance</h2><p>Recorded spend against allocated budget · NOK</p></div></div><div class="panel-body">${ps.length?ps.map(p=>`<div class="budget-row"><span>${esc(p.name)}</span><small class="${p.spent>p.budget?'overdue':''}">${shortMoney(p.spent)} / ${shortMoney(p.budget)} NOK</small>${bar(p.budget?Math.min(100,Math.round(p.spent/p.budget*100)):0,p.color)}</div>`).join(''):empty('No budgets in this view.')}</div></section><section class="panel"><div class="panel-head"><div><h2>Work distribution</h2><p>Task ownership across your portfolio</p></div></div><div class="panel-body">${[...new Set(ts.map(t=>t.owner))].map(owner=>{const owned=ts.filter(t=>t.owner===owner),done=owned.filter(t=>t.status==='Done').length;return `<div class="budget-row"><span class="owner">${avatar(owner)}${esc(owner)}</span><small>${done} / ${owned.length} complete</small>${bar(Math.round(done/owned.length*100))}</div>`}).join('')||empty('Add tasks to see workload.')}</div></section><section class="panel"><div class="panel-head"><div><h2>A moment to reflect</h2><p>Where a little attention could help</p></div></div><div class="panel-body"><div class="storage-notice">${blocked?`${blocked} blocked ${blocked===1?'task needs':'tasks need'} a next step. Review dependencies and agree ownership.`:'No blocked tasks in this view. Keep the path clear with regular check-ins.'}</div><h3 style="font-size:.875rem;margin-top:24px">Recent workspace activity</h3>${data.activity.slice(0,5).map(a=>`<div class="activity-row">${esc(a.text)}<small>${new Date(a.at).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||empty('Activity will appear as you work.')}</div></section></div><p class="note" style="line-height:1.8;margin-top:20px">Progress counts completed tasks equally. Planned trends use current task due dates; actual trends use completion dates. Changing scope or dates recalculates the baseline. Budget figures are entered manually.</p>`}
function risks(){const ps=scoped(),rs=data.risks.filter(r=>ps.some(p=>p.id===r.projectId));return heading('A little foresight goes a long way.','Make uncertainty visible. Give every risk a clear next step.',`${yearSelect()}<button class="primary" data-action="new-risk">${icon('plus')}New risk</button>`)+periodbar()+`<section class="panel table-wrap"><table><thead><tr><th>Risk & response</th><th>Project</th><th>Impact</th><th>Likelihood</th><th>Owner</th><th>Status</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td class="risk-description"><strong style="font-weight:500">${esc(r.name)}</strong><small style="display:block;color:var(--muted);margin-top:8px">${esc(r.mitigation)}</small></td><td>${esc(pname(r.projectId))}</td><td>${badge(r.impact)}</td><td>${r.likelihood}</td><td>${esc(r.owner)}</td><td>${badge(r.status)}</td><td><button class="text-button" data-edit="risk:${r.id}" aria-label="Edit ${esc(r.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table>${!rs.length?empty('A clear horizon. Add risks as you discover them.'):''}</section>`}
function settings(){return heading('A workspace that feels like yours.','Simple settings, a clear home for your data.')+`<div class="settings-grid"><section class="panel panel-body"><h2>Your workspace</h2><form id="workspace-form"><div class="form-grid" style="margin-top:20px"><label class="full">Workspace name<input name="workspace" maxlength="60" required value="${esc(data.workspace)}"></label></div><button class="primary" style="margin-top:18px">Save workspace name</button></form><h3>Private to this browser</h3><p>Your data is stored in this browser on this device. It is not synced with a team or another device. Export a backup regularly, especially before clearing browser data.</p><div class="storage-notice">${data.demo?'You’re exploring an example workspace. Edit these records, or start with an empty workspace below.':'This is your own workspace. Keep a backup for peace of mind.'}</div></section><section class="panel panel-body"><h2>Backups & reports</h2><p>A JSON backup includes projects, tasks, milestones, risks and activity. Import replaces the current workspace after confirmation. CSV reports include projects in the selected year and quarter.</p><div class="actions"><button data-action="backup">${icon('download')}Download backup</button><button data-action="import">Import backup</button><button data-action="export-csv">Export project CSV</button><input type="file" id="import-file" accept=".json,application/json" hidden></div></section><section class="panel panel-body"><h2>A fresh page</h2><p>Start an empty workspace, or restore the example projects. Download a backup first if you want to keep your current records.</p><div class="actions"><button data-action="clear" class="danger">Start empty workspace</button><button data-action="restore">Restore examples</button></div></section></div>`}
function modal(title,body){$('#modal').classList.remove('project-dialog');$('#modal').innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="ghost" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function responsibleOptions(){return `<datalist id="responsible-options">${[...new Set([...data.projects.map(p=>p.owner),...data.tasks.map(t=>t.owner)])].filter(Boolean).sort().map(name=>`<option value="${esc(name)}"></option>`).join('')}</datalist>`}
function deadlineDefault(p){return p?.due>=today()?p.due:today()}
function detail(pid){
 const p=findP(pid);if(!p)return;
 const ts=data.tasks.filter(t=>t.projectId===pid).sort((a,b)=>(a.status==='Done')-(b.status==='Done')||a.due.localeCompare(b.due));
 modal(esc(p.name),`<div class="detail-meta"><span id="detail-health">${badge(health(p,data.tasks))}</span><span class="owner">${avatar(p.owner)}${esc(p.owner)}</span></div><p>${esc(p.description)}</p><div class="detail-stat"><div>Progress<strong>${progress(p,data.tasks)}%</strong></div><div>Project deadline<strong>${fmt(p.due)}</strong></div><div>Tasks complete<strong>${ts.filter(t=>t.status==='Done').length} / ${ts.length}</strong></div></div>${bar(progress(p,data.tasks),p.color)}
 <section class="quick-task"><h3>Add a task</h3><p>Name the next step, choose who’s responsible, and set a deadline.</p><form id="quick-task-form" data-project="${pid}"><div class="quick-task-fields"><label class="task-name">Task name<input name="name" placeholder="What needs to be done?" maxlength="160" required></label><label>Responsible<input name="owner" list="responsible-options" value="${esc(p.owner)}" placeholder="Choose or type a name" maxlength="160" required></label><label>Deadline<input name="due" type="date" value="${deadlineDefault(p)}" required></label><button class="primary">${icon('plus')}Add task</button></div><p class="form-error" id="quick-task-error" role="alert"></p></form></section>
 <div class="section-title"><h3 style="margin:0">Project tasks <span class="note">${ts.length}</span></h3><span class="note">Responsible & deadlines save as you change them</span></div>
 <div class="project-task-list">${ts.length?ts.map(t=>`<div class="project-task-row ${t.status==='Done'?'done':''}"><div class="task-title"><input id="check-${t.id}" type="checkbox" data-complete="${t.id}" data-detail-context="${pid}" ${t.status==='Done'?'checked':''}><label for="check-${t.id}">${esc(t.name)}</label>${badge(t.status)}</div><div class="task-assignment"><label>Responsible<input value="${esc(t.owner)}" list="responsible-options" data-task-field="owner" data-task-id="${t.id}" maxlength="160" required aria-label="Responsible for ${esc(t.name)}"></label><label>Deadline<input type="date" value="${t.due}" data-task-field="due" data-task-id="${t.id}" required aria-label="Deadline for ${esc(t.name)}" class="${t.status!=='Done'&&t.due<today()?'overdue':''}"></label><button class="ghost" data-edit="task:${t.id}" aria-label="Edit ${esc(t.name)}">${icon('edit')}</button></div></div>`).join(''):empty('No tasks yet. Add your first task above.')}</div>${responsibleOptions()}<div class="modal-actions"><button data-edit="project:${pid}">Edit project</button><button data-action="close">Done</button></div>`);
 $('#modal').classList.add('project-dialog');
}
const collections={project:'projects',task:'tasks',milestone:'milestones',risk:'risks'};
function edit(type,recordId,projectId){if(type!=='project'&&!data.projects.length){toast('Create a project first.');edit('project');return}const returnProject=type==='task'?$('#quick-task-form')?.dataset.project:'';const old=recordId?data[collections[type]].find(x=>x.id===recordId):null;if(recordId&&!old)return;const selectedProject=findP(projectId)||(type==='task'&&state.project!=='all'?findP(state.project):null)||data.projects[0];const r=old||{projectId:selectedProject?.id,owner:type==='task'?selectedProject?.owner||'':'',start:today(),due:type==='task'?deadlineDefault(selectedProject):today(),budget:0,spent:0,priority:'Medium',status:type==='risk'?'Open':'To do',impact:'Medium',likelihood:'Medium',color:'olive'};const field=(label,name,inputType='text',full=false)=>`<label class="${full?'full':''}">${label}<input name="${name}" type="${inputType}" ${inputType==='number'?'min="0" step="0.01"':'maxlength="160"'} value="${esc(r[name]??'')}" required></label>`;const select=(label,name,options)=>`<label>${label}<select name="${name}">${options.map(v=>`<option ${v===r[name]?'selected':''}>${v}</option>`).join('')}</select></label>`;let fields=field(type==='project'?'Project name':type==='task'?'Task name':type==='milestone'?'Milestone name':'Risk','name','text',true);
if(type!=='project')fields+=`<label class="full">Project<select name="projectId">${projectOptions(r.projectId,false)}</select></label>`;
if(type==='project')fields+=`<label class="full">Description<textarea name="description" maxlength="2000">${esc(r.description||'')}</textarea></label>`+field('Project lead','owner')+select('Project accent','color',['olive','clay','sand','slate'])+field('Start date','start','date')+field('Due date','due','date')+field('Allocated budget (NOK)','budget','number')+field('Recorded spend (NOK)','spent','number');
if(type==='task')fields+=`<label>Responsible<input name="owner" list="responsible-options" maxlength="160" value="${esc(r.owner)}" placeholder="Choose or type a name" required></label>`+field('Deadline','due','date')+`<details class="full task-options" ${old?'open':''}><summary>Status & priority</summary><div class="form-grid">`+select('Status','status',['To do','In progress','Blocked','Done'])+select('Priority','priority',['Low','Medium','High'])+`<label class="full">Completion date (for completed tasks)<input name="completedAt" type="date" value="${esc(r.completedAt||'')}"></label></div></details>`+responsibleOptions();
if(type==='milestone')fields+=field('Target date','due','date')+`<label style="justify-content:center"><span><input name="done" type="checkbox" ${r.done?'checked':''}> Completed milestone</span></label>`;
if(type==='risk')fields+=field('Owner','owner')+select('Status','status',['Open','Mitigated','Closed'])+select('Impact','impact',['Low','Medium','High'])+select('Likelihood','likelihood',['Low','Medium','High'])+`<label class="full">Response / mitigation<textarea name="mitigation" required maxlength="2000">${esc(r.mitigation||'')}</textarea></label>`;
modal(`${old?'Edit':'New'} ${type}`,`<form id="edit-form" data-type="${type}" data-id="${recordId||''}" data-return-project="${returnProject||''}"><div class="form-grid">${fields}</div><p class="form-error" id="form-error" role="alert"></p><div class="modal-actions">${old?`<button type="button" class="danger" data-delete="${type}:${recordId}">Delete ${type}</button>`:''}<button type="button" data-action="close">Cancel</button>${type==='task'&&!old?'<button name="next" value="another">Create & add another</button>':''}<button class="primary">${old?'Save changes':`Create ${type}`}</button></div></form>`)}
function confirmAction(title,description,action){modal(title,`<p>${description}</p><div class="modal-actions"><button data-action="close">Cancel</button><button class="primary" id="confirm-button">Confirm</button></div>`);$('#confirm-button').onclick=action}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(){const rows=[['Project','Lead','Start','Due','Health','Progress %','Tasks','Completed','Budget NOK','Spent NOK'],...scoped().map(p=>{const ts=data.tasks.filter(t=>t.projectId===p.id);return[p.name,p.owner,p.start,p.due,health(p,data.tasks),progress(p,data.tasks),ts.length,ts.filter(t=>t.status==='Done').length,p.budget,p.spent]})];download('\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),`prosjektledelse-${state.year}${state.q?'-Q'+state.q:''}.csv`,'text/csv;charset=utf-8');toast('Project report exported')}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.nav){state.page=el.dataset.nav;state.search='';location.hash=state.page;document.body.classList.remove('menu-open');render();return}if(el.dataset.quarter!==undefined){state.q=+el.dataset.quarter;render();return}if(el.dataset.view){state.taskView=el.dataset.view;render();return}if(el.dataset.detail){detail(el.dataset.detail);return}if(el.dataset.edit){edit(...el.dataset.edit.split(':'));return}if(el.dataset.newProjectTask){edit('task',null,el.dataset.newProjectTask);return}if(el.dataset.delete){const[type,recordId]=el.dataset.delete.split(':');confirmAction(`Delete this ${type}?`,type==='project'?'This also deletes its tasks, milestones and risks. Export a backup from Settings if you want to keep a copy.':'This record will be removed. Export a backup if you want to keep a copy.',()=>{data[collections[type]]=data[collections[type]].filter(x=>x.id!==recordId);if(type==='project')for(const k of ['tasks','milestones','risks'])data[k]=data[k].filter(x=>x.projectId!==recordId);log(`Deleted a ${type}`);save(`${type} deleted`);$('#modal').close();render()});return}const action=el.dataset.action;if(!action)return;
if(action==='menu'){document.body.classList.toggle('menu-open');return}if(action==='close'){$('#modal').close();return}if(action.startsWith('new-')){edit(action.slice(4));return}if(action==='export-csv'){csv();return}if(action==='backup'){download(JSON.stringify(data,null,2),`prosjektledelse-backup-${today()}.json`,'application/json');toast('Backup downloaded');return}if(action==='import'){$('#import-file').click();return}if(action==='clear'||action==='restore'){confirmAction(action==='clear'?'Start with a fresh page?':'Restore example workspace?','This replaces all current records on this device. Download a backup first if you want to keep them.',()=>{data=action==='restore'?seed():{version:1,workspace:data.workspace,demo:false,projects:[],tasks:[],milestones:[],risks:[],activity:[]};state.project='all';save('Workspace ready');$('#modal').close();render()})}});
document.addEventListener('change',async e=>{const el=e.target;if(el.name==='projectId'&&el.closest('#edit-form')?.dataset.type==='task'&&!el.closest('#edit-form').dataset.id){const p=findP(el.value);const form=el.closest('form');form.elements.owner.value=p.owner;form.elements.due.value=deadlineDefault(p)}if(el.dataset.taskField){const task=data.tasks.find(t=>t.id===el.dataset.taskId);const value=el.value.trim();if(!value||!el.checkValidity()){el.value=task[el.dataset.taskField];toast('Please enter a responsible person and a valid deadline.');return}if(task[el.dataset.taskField]===value)return;task[el.dataset.taskField]=value;log(`Updated ${el.dataset.taskField==='owner'?'responsible person':'deadline'} for “${task.name}”`);save('Task updated');render();const p=findP(task.projectId);$('#detail-health').innerHTML=badge(health(p,data.tasks));if(el.dataset.taskField==='due')el.classList.toggle('overdue',task.status!=='Done'&&task.due<today());return}if(el.id==='year'){state.year=+el.value;render()}if(el.id==='project-filter'){state.project=el.value;render()}if(el.id==='status-filter'){state.taskStatus=el.value;render()}if(el.dataset.complete){const t=data.tasks.find(t=>t.id===el.dataset.complete);t.status=el.checked?'Done':'To do';t.completedAt=el.checked?today():null;log(`${el.checked?'Completed':'Reopened'} “${t.name}”`);save(el.checked?'One more step forward.':'Task reopened');render();if(el.dataset.detailContext)detail(el.dataset.detailContext)}if(el.id==='import-file'&&el.files[0]){try{if(el.files[0].size>5e6)throw Error('Please choose a backup smaller than 5 MB.');const imported=validateData(JSON.parse(await el.files[0].text()));confirmAction('Replace workspace from backup?',`This imports ${imported.projects.length} projects and ${imported.tasks.length} tasks, replacing your current data.`,()=>{data=imported;state.project='all';save('Backup restored');$('#modal').close();render()})}catch(err){toast(err.message)}el.value=''}});
document.addEventListener('input',e=>{if(e.target.id==='project-search'){const pos=e.target.selectionStart;state.search=e.target.value;render();const input=$('#project-search');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{if(e.target.id==='quick-task-form'){
 e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form));values.name=values.name.trim();values.owner=values.owner.trim();if(!values.name||!values.owner){$('#quick-task-error').textContent='Enter a task name and responsible person.';return}
 data.tasks.push({id:id(),projectId:form.dataset.project,...values,status:'To do',priority:'Medium',completedAt:null});log(`Created task “${values.name}” in ${pname(form.dataset.project)}`);save('Task added. Ready for the next one.');render();detail(form.dataset.project);$('#quick-task-form').elements.owner.value=values.owner;$('#quick-task-form').elements.due.value=values.due;$('#quick-task-form').elements.name.focus();return
}if(e.target.id==='workspace-form'){e.preventDefault();const value=new FormData(e.target).get('workspace').trim();if(!value)return;data.workspace=value;save('Workspace name saved');render();return}if(e.target.id!=='edit-form')return;e.preventDefault();const type=e.target.dataset.type,recordId=e.target.dataset.id,old=data[collections[type]].find(x=>x.id===recordId),values=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(values))if(typeof values[k]==='string')values[k]=values[k].trim();if(!values.name||('owner'in values&&!values.owner)){$('#form-error').textContent='Please enter a name and owner.';return}if(type==='project'){values.budget=+values.budget;values.spent=+values.spent;if(values.start>values.due){$('#form-error').textContent='The due date must be on or after the start date.';return}}
if(type==='milestone')values.done=new FormData(e.target).has('done');if(type==='task'){values.completedAt=values.status==='Done'?(values.completedAt||old?.completedAt||today()):null;if(values.completedAt>today()){$('#form-error').textContent='Completion dates cannot be in the future.';return}}
const record={...old,...values,id:recordId||id()};if(old)data[collections[type]][data[collections[type]].indexOf(old)]=record;else data[collections[type]].push(record);log(`${old?'Updated':'Created'} ${type} “${record.name}”`);save(`${type[0].toUpperCase()+type.slice(1)} ${old?'updated':'created'}`);const returnProject=e.target.dataset.returnProject;const another=e.submitter?.value==='another';$('#modal').close();render();if(type==='task'&&another){edit('task',null,record.projectId);const form=$('#edit-form');form.elements.owner.value=record.owner;form.elements.due.value=record.due;form.dataset.returnProject=returnProject||'';form.elements.name.focus()}else if(type==='task'&&returnProject){detail(returnProject)}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(names[page]){state.page=page;render()}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
render();if(loadError)toast('Saved data could not be loaded. Examples are shown; your previous storage has not been overwritten.');
